// HYP-001: Test state machine parser for indentation-based YAML parsing

type ParsedValue = string | number | boolean | null | Record<string, any> | any[];

interface ParseState {
  level: number;
  current: Record<string, ParsedValue>;
  stack: Array<{ level: number; obj: Record<string, ParsedValue>; key?: string }>;
  currentList?: ParsedValue[];
}

class YamlParser {
  private lines: string[];
  private state: ParseState;

  constructor(content: string) {
    this.lines = content.split('\n');
    this.state = {
      level: 0,
      current: {},
      stack: [],
      currentList: undefined,
    };
  }

  parse(): Record<string, ParsedValue> {
    for (let i = 0; i < this.lines.length; i++) {
      const line = this.lines[i];

      // Skip empty lines and comments
      if (!line.trim() || line.trim().startsWith('#')) continue;

      // Detect indentation
      const indentMatch = line.match(/^(\s*)/);
      const indent = indentMatch ? indentMatch[1].length : 0;
      const content = line.trim();

      // Check for mixed tabs/spaces (indentation error)
      if (/^\s*[\t ]+/.test(line) && /\t/.test(indentMatch![1]) && / /.test(indentMatch![1])) {
        throw new Error(`Line ${i + 1}: Mixed tabs and spaces`);
      }

      // Handle indentation levels
      if (indent % 2 !== 0) {
        throw new Error(`Line ${i + 1}: Invalid indentation level (not multiple of 2)`);
      }

      const level = indent / 2;

      // Parse key-value or list items
      if (content.startsWith('- ')) {
        // List item
        const value = content.substring(2).trim();
        if (!this.state.currentList) {
          this.state.currentList = [];
        }
        this.state.currentList.push(this._parseValue(value));
      } else if (content.includes(':')) {
        // Key-value pair
        const [key, ...valueParts] = content.split(':');
        const value = valueParts.join(':').trim();

        // Pop stack if we've decreased indentation
        while (this.state.stack.length > level) {
          const popped = this.state.stack.pop();
          if (popped) {
            this.state.level = popped.level;
            this.state.current = popped.obj;
          }
        }

        // Add to current object
        if (value === '' || value === null || value === undefined) {
          // Nested object follows
          const newObj: Record<string, ParsedValue> = {};
          this.state.current[key.trim()] = newObj;
          this.state.stack.push({
            level: this.state.level,
            obj: this.state.current,
            key: key.trim(),
          });
          this.state.current = newObj;
          this.state.level = level;
        } else {
          this.state.current[key.trim()] = this._parseValue(value);
        }
      }
    }

    // Return root object
    while (this.state.stack.length > 0) {
      const popped = this.state.stack.pop();
      if (popped) {
        this.state.current = popped.obj;
      }
    }

    return this.state.current;
  }

  private _parseValue(val: string): ParsedValue {
    if (val === 'null' || val === '') return null;
    if (val === 'true') return true;
    if (val === 'false') return false;
    if (!isNaN(Number(val))) return Number(val);
    return val;
  }
}

// Test cases
console.log('=== HYP-001: State Machine Parser Test ===\n');

// Test 1: Simple nested structure
