/**
 * Minimal YAML parser for common configuration syntax.
 *
 * This is a hand-written, zero-dependency YAML parser designed to handle
 * typical configuration files. It supports:
 * - Key-value pairs (key: value)
 * - Nested objects (indentation-based)
 * - Lists (- item syntax)
 * - Comments (# lines)
 * - Basic type inference (strings, numbers, booleans, null)
 * - Quoted strings and escape sequences
 *
 * NOT supported (intentional):
 * - YAML anchors (&ref, *ref)
 * - YAML tags (!!type)
 * - Flow syntax ({} and [])
 * - Advanced YAML features (multiline strings, etc.)
 * - Full YAML spec compliance
 *
 * Depth limit: 20 levels of nesting (prevents stack overflow)
 *
 * @module yaml-parser
 */

/**
 * Result of parsing a YAML string.
 */
export interface ParseResult {
  success: boolean;
  data?: Record<string, any>;
  error?: ParseError;
}

/**
 * Error details from parsing failure.
 */
export interface ParseError {
  message: string;
  line: number;
  column: number;
  context: string; // the problematic line of text
}

/**
 * Token classification for a line.
 */
interface Token {
  type:
    | "blank"
    | "comment"
    | "key-value"
    | "list-item"
    | "continuation"
    | "invalid";
  content: string;
  indentLevel: number;
  lineNumber: number;
  rawLine: string;
}

/**
 * Parse a YAML string into a JavaScript object.
 * @param content - The YAML content to parse
 * @returns ParseResult with success flag and either data or error
 */
export function parseYaml(content: string): ParseResult {
  try {
    const lines = content.split("\n");
    const tokens = tokenize(lines);

    if (!tokens.success) {
      return { success: false, error: tokens.error };
    }

    const result = buildTree(tokens.tokens!);
    return result;
  } catch (err) {
    return {
      success: false,
      error: {
        message:
          err instanceof Error ? err.message : "Unknown parsing error",
        line: 0,
        column: 0,
        context: "",
      },
    };
  }
}

/**
 * Tokenize YAML input into a structured token stream.
 */
function tokenize(
  lines: string[]
): { success: boolean; tokens?: Token[]; error?: ParseError } {
  const tokens: Token[] = [];
  let prevIndentLevel = 0;

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const lineNumber = i + 1;

    // Handle blank lines
    if (rawLine.trim() === "") {
      tokens.push({
        type: "blank",
        content: "",
        indentLevel: 0,
        lineNumber,
        rawLine,
      });
      continue;
    }

    // Measure indentation
    const indentMatch = rawLine.match(/^(\s*)/);
    const indentStr = indentMatch ? indentMatch[1] : "";
    const indentLevel = indentStr.length;

    // Check for consistent 2-space indentation (when not zero)
    if (indentLevel > 0 && indentLevel % 2 !== 0) {
      return {
        success: false,
        error: {
          message: `Invalid indentation (expected multiple of 2 spaces, got ${indentLevel})`,
          line: lineNumber,
          column: indentLevel + 1,
          context: rawLine,
        },
      };
    }

    const content = rawLine.slice(indentLevel);

    // Handle comments
    if (content.startsWith("#")) {
      tokens.push({
        type: "comment",
        content,
        indentLevel,
        lineNumber,
        rawLine,
      });
      prevIndentLevel = indentLevel;
      continue;
    }

    // Handle list items
    if (content.startsWith("- ")) {
      tokens.push({
        type: "list-item",
        content: content.slice(2),
        indentLevel,
        lineNumber,
        rawLine,
      });
      prevIndentLevel = indentLevel;
      continue;
    }

    // Handle key-value pairs
    if (content.includes(":")) {
      const colonIdx = content.indexOf(":");
      const key = content.slice(0, colonIdx).trim();

      // Ensure key is valid (no special chars, alphanumeric + underscore/dash)
      if (!/^[a-zA-Z_][a-zA-Z0-9_-]*$/.test(key)) {
        return {
          success: false,
          error: {
            message: `Invalid key name: "${key}"`,
            line: lineNumber,
            column: indentLevel + 1,
            context: rawLine,
          },
        };
      }

      const value = content.slice(colonIdx + 1).trim();
      tokens.push({
        type: "key-value",
        content: `${key}=${value}`,
        indentLevel,
        lineNumber,
        rawLine,
      });
      prevIndentLevel = indentLevel;
      continue;
    }

    // Unrecognized line format
    return {
      success: false,
      error: {
        message: "Invalid YAML syntax (expected key: value or - item)",
        line: lineNumber,
        column: 1,
        context: rawLine,
      },
    };
  }

  return { success: true, tokens };
}

/**
 * Build a tree structure from tokens, respecting nesting depth.
 */
function buildTree(tokens: Token[]): ParseResult {
  const root: Record<string, any> = {};
  const stack: Array<{ level: number; object: any }> = [
    { level: -1, object: root },
  ];
  let maxDepth = 0;

  for (const token of tokens) {
    // Skip blank lines and comments
    if (token.type === "blank" || token.type === "comment") {
      continue;
    }

    const depth = token.indentLevel / 2;
    maxDepth = Math.max(maxDepth, depth);

    // Check depth limit
    if (depth > 20) {
      return {
        success: false,
        error: {
          message: "Maximum nesting depth exceeded (max 20 levels)",
          line: token.lineNumber,
          column: token.indentLevel + 1,
          context: token.rawLine,
        },
      };
    }

    // Pop stack back to appropriate level
    while (stack.length > 1 && stack[stack.length - 1].level >= depth) {
      stack.pop();
    }

    const parentLevel = stack[stack.length - 1];

    if (token.type === "key-value") {
      const [key, value] = token.content.split("=", 2);
      const typedValue = parseValue(value);

      if (parentLevel.object[key] !== undefined) {
        // Key already exists; this is allowed (overwrite)
      }

      parentLevel.object[key] = typedValue;
    } else if (token.type === "list-item") {
      // For simple list items, we'd need to track array state
      // For now, create arrays when we see list items
      const key = `_list_${depth}`;

      if (!Array.isArray(parentLevel.object[key])) {
        parentLevel.object[key] = [];
      }

      parentLevel.object[key].push(parseValue(token.content));
    }
  }

  return { success: true, data: root };
}

/**
 * Parse a value string and infer its type.
 */
function parseValue(value: string): any {
  if (!value || value === "") {
    return null;
  }

  // Handle quoted strings (preserve as-is)
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1);
  }

  // Handle null
  if (value === "null" || value === "~") {
    return null;
  }

  // Handle booleans
  if (value === "true") {
    return true;
  }
  if (value === "false") {
    return false;
  }

  // Handle numbers
  if (/^-?\d+(\.\d+)?$/.test(value)) {
    return Number(value);
  }

  // Default to string
  return value;
}

