/**
 * Build a tree structure from tokens, respecting nesting depth.
 */
function buildTree(tokens: Token[]): ParseResult {
  const root: Record<string, any> = {};
  const stack: Array<{ level: number; key: string | null; object: any }> = [
    { level: -2, key: null, object: root },
  ];

  for (const token of tokens) {
    // Skip blank lines and comments
    if (token.type === "blank" || token.type === "comment") {
      continue;
    }

    const depth = token.indentLevel / 2;

    // Check depth limit
    if (depth > 20) {
      return {
        success: false,
        error: {
          message: "Maximum nesting depth exceeded (max 20 levels)",
          line: token.lineNumber,
          column: token.indentLevel + 1,
          context: token.rawLine,
        },
      };
    }

    // Pop stack back to appropriate level
    while (stack.length > 1 && stack[stack.length - 1].level >= depth) {
      stack.pop();
    }

    if (token.type === "key-value") {
      const [key, value] = token.content.split("=", 2);
      const typedValue = parseValue(value);
      const parent = stack[stack.length - 1].object;

      // If value is empty, this key might have children (nested object)
      if (value === "" || value.trim() === "") {
        const nestedObj: Record<string, any> = {};
        parent[key] = nestedObj;
        stack.push({ level: depth, key, object: nestedObj });
      } else {
        parent[key] = typedValue;
      }
    } else if (token.type === "list-item") {
      const parent = stack[stack.length - 1].object;
      const currentKey = stack[stack.length - 1].key;

      // If parent is the key from the previous level, convert it to array
      if (currentKey && !Array.isArray(parent[currentKey])) {
        parent[currentKey] = [];
      }

      // Get or create the array for list items
      let listArray = parent._items;
      if (!listArray) {
        listArray = [];
        parent._items = listArray;
      }

      listArray.push(parseValue(token.content));
    }
  }

  return { success: true, data: root };
}

