    66→        line: 0,
    67→        column: 0,
    68→        context: "",
    69→      },
    70→    };
    71→  }
    72→}
    73→
    74→/**
    75→ * Parse lines into a YAML structure.
    76→ */
    77→function parseLines(lines: string[]): ParseResult {
    78→  const root: Record<string, any> = {};
    79→  const stack: StackFrame[] = [
    80→    { level: -1, key: null, object: root, listKey: null },
    81→  ];
    82→
    83→  for (let i = 0; i < lines.length; i++) {
    84→    const line = lines[i];
    85→    const lineNumber = i + 1;
    86→
    87→    // Skip blank lines
    88→    if (line.trim() === "") {
    89→      continue;
    90→    }
    91→
    92→    // Skip comments
    93→    if (line.trim().startsWith("#")) {
    94→      continue;
    95→    }
    96→
    97→    const indent = getIndentation(line);
    98→    const indentLevel = indent.length / 2;
    99→    const content = line.slice(indent.length);
   100→
   101→    // Validate indentation
   102→    if (indent.length > 0 && indent.length % 2 !== 0) {
   103→      return {
   104→        success: false,
   105→        error: {
   106→          message: `Invalid indentation (expected multiple of 2 spaces, got ${indent.length})`,
   107→          line: lineNumber,
   108→          column: indent.length + 1,
   109→          context: line,
   110→        },
   111→      };
   112→    }
   113→
   114→    // Check depth limit
   115→    if (indentLevel > 20) {
   116→      return {
   117→        success: false,
   118→        error: {
   119→          message: "Maximum nesting depth exceeded (max 20 levels)",
   120→          line: lineNumber,
   121→          column: indent.length + 1,
   122→          context: line,
   123→        },
   124→      };
   125→    }
   126→
   127→    // Pop stack to current indent level
   128→    while (
   129→      stack.length > 1 &&
   130→      stack[stack.length - 1].level >= indentLevel
   131→    ) {
   132→      stack.pop();
   133→    }
   134→
   135→    const current = stack[stack.length - 1];
   136→
   137→    // Handle list items
   138→    if (content.startsWith("- ")) {
