   190→        if (isListKey) {
   191→          // Initialize as an empty array that we'll populate
   192→          current.object[key] = [];
   193→          // Push frame to track that this is a list key
   194→          stack.push({
   195→            level: indentLevel,
   196→            key,
   197→            object: current.object,
   198→            listKey: key,
   199→          });
   200→        } else {
   201→          // Regular nested object
   202→          const nested: Record<string, any> = {};
   203→          current.object[key] = nested;
   204→          stack.push({
   205→            level: indentLevel,
   206→            key,
   207→            object: nested,
   208→            listKey: null,
   209→          });
   210→        }
   211→      } else {
   212→        // Immediate value
   213→        const typedValue = parseValue(value);
   214→        current.object[key] = typedValue;
