     1→/**
     2→ * Minimal YAML parser for common configuration syntax.
     3→ *
     4→ * This is a hand-written, zero-dependency YAML parser designed to handle
     5→ * typical configuration files. It supports:
     6→ * - Key-value pairs (key: value)
     7→ * - Nested objects (indentation-based)
     8→ * - Lists (- item syntax)
     9→ * - Comments (# lines)
    10→ * - Basic type inference (strings, numbers, booleans, null)
    11→ * - Quoted strings and escape sequences
    12→ *
    13→ * NOT supported (intentional):
    14→ * - YAML anchors (&ref, *ref)
    15→ * - YAML tags (!!type)
    16→ * - Flow syntax ({} and [])
    17→ * - Advanced YAML features (multiline strings, etc.)
    18→ * - Full YAML spec compliance
    19→ *
    20→ * Depth limit: 20 levels of nesting (prevents stack overflow)
    21→ *
    22→ * @module yaml-parser
    23→ */
    24→
    25→/**
    26→ * Result of parsing a YAML string.
    27→ */
    28→export interface ParseResult {
    29→  success: boolean;
    30→  data?: Record<string, any>;
    31→  error?: ParseError;
    32→}
    33→
    34→/**
    35→ * Error details from parsing failure.
    36→ */
    37→export interface ParseError {
    38→  message: string;
    39→  line: number;
    40→  column: number;
    41→  context: string; // the problematic line of text
    42→}
    43→
    44→interface StackFrame {
    45→  level: number;
    46→  key: string | null;
    47→  object: Record<string, any>;
    48→  listKey: string | null; // if this frame is for a list's parent key
    49→}
    50→
    51→/**
    52→ * Parse a YAML string into a JavaScript object.
    53→ * @param content - The YAML content to parse
    54→ * @returns ParseResult with success flag and either data or error
    55→ */
    56→export function parseYaml(content: string): ParseResult {
    57→  try {
    58→    const lines = content.split("\n");
    59→    return parseLines(lines);
    60→  } catch (err) {
    61→    return {
    62→      success: false,
    63→      error: {
    64→        message:
    65→          err instanceof Error ? err.message : "Unknown parsing error",
    66→        line: 0,
    67→        column: 0,
    68→        context: "",
    69→      },
    70→    };
    71→  }
    72→}
    73→
    74→/**
    75→ * Parse lines into a YAML structure.
    76→ */
    77→function parseLines(lines: string[]): ParseResult {
    78→  const root: Record<string, any> = {};
    79→  const stack: StackFrame[] = [
    80→    { level: -1, key: null, object: root, listKey: null },
    81→  ];
    82→
    83→  for (let i = 0; i < lines.length; i++) {
    84→    const line = lines[i];
    85→    const lineNumber = i + 1;
    86→
    87→    // Skip blank lines
    88→    if (line.trim() === "") {
    89→      continue;
    90→    }
    91→
    92→    // Skip comments
    93→    if (line.trim().startsWith("#")) {
    94→      continue;
    95→    }
    96→
    97→    const indent = getIndentation(line);
    98→    const indentLevel = indent.length / 2;
    99→    const content = line.slice(indent.length);
   100→
   101→    // Validate indentation
