   103→      return {
   104→        success: false,
   105→        error: {
   106→          message: `Invalid indentation (expected multiple of 2 spaces, got ${indent.length})`,
   107→          line: lineNumber,
   108→          column: indent.length + 1,
   109→          context: line,
   110→        },
   111→      };
   112→    }
   113→
   114→    // Check depth limit
   115→    if (indentLevel > 20) {
   116→      return {
   117→        success: false,
   118→        error: {
   119→          message: "Maximum nesting depth exceeded (max 20 levels)",
   120→          line: lineNumber,
   121→          column: indent.length + 1,
   122→          context: line,
   123→        },
   124→      };
   125→    }
   126→
   127→    // Pop stack to current indent level
   128→    while (
   129→      stack.length > 1 &&
   130→      stack[stack.length - 1].level >= indentLevel
   131→    ) {
   132→      stack.pop();
   133→    }
   134→
   135→    const current = stack[stack.length - 1];
   136→
   137→    // Handle list items
   138→    if (content.startsWith("- ")) {
   139→      const value = content.slice(2).trim();
