   143→      // The list key should be the last key added at this indent level
   144→      if (current.listKey) {
   145→        // We're adding to an existing array
   146→        if (!Array.isArray(current.object[current.listKey])) {
   147→          current.object[current.listKey] = [];
   148→        }
   149→        (current.object[current.listKey] as any[]).push(typedValue);
   150→      }
   151→    } else if (content.includes(":")) {
   152→      // Key-value pair
   153→      const colonIdx = content.indexOf(":");
   154→      const key = content.slice(0, colonIdx).trim();
   155→      const value = content.slice(colonIdx + 1).trim();
   156→
   157→      // Validate key
   158→      if (!/^[a-zA-Z_][a-zA-Z0-9_-]*$/.test(key)) {
   159→        return {
   160→          success: false,
   161→          error: {
   162→            message: `Invalid key name: "${key}"`,
   163→            line: lineNumber,
   164→            column: indent.length + 1,
   165→            context: line,
   166→          },
   167→        };
   168→      }
   169→
   170→      if (value === "") {
   171→        // This key will have nested content
   172→        // Look ahead to see if the next line is a list item
   173→        let isListKey = false;
   174→        for (let j = i + 1; j < lines.length; j++) {
   175→          const nextLine = lines[j];
   176→          if (nextLine.trim() === "" || nextLine.trim().startsWith("#")) {
   177→            continue;
   178→          }
   179→          const nextIndent = getIndentation(nextLine);
   180→          const nextIndentLevel = nextIndent.length / 2;
   181→          if (nextIndentLevel > indentLevel) {
   182→            const nextContent = nextLine.slice(nextIndent.length);
   183→            if (nextContent.startsWith("- ")) {
   184→              isListKey = true;
   185→            }
   186→          }
   187→          break;
   188→        }
   189→
   190→        if (isListKey) {
   191→          // Initialize as an empty array that we'll populate
   192→          current.object[key] = [];
   193→          // Push frame to track that this is a list key
   194→          stack.push({
   195→            level: indentLevel,
   196→            key,
   197→            object: current.object,
   198→            listKey: key,
   199→          });
   200→        } else {
   201→          // Regular nested object
   202→          const nested: Record<string, any> = {};
   203→          current.object[key] = nested;
   204→          stack.push({
   205→            level: indentLevel,
   206→            key,
   207→            object: nested,
   208→            listKey: null,
   209→          });
   210→        }
   211→      } else {
   212→        // Immediate value
   213→        const typedValue = parseValue(value);
   214→        current.object[key] = typedValue;
   215→
   216→        // Update list key if we just assigned a value to what was a list key
   217→        if (current.listKey === key) {
   218→          current.listKey = null;
   219→        }
   220→      }
   221→    } else {
   222→      // Invalid syntax
   223→      return {
   224→        success: false,
   225→        error: {
   226→          message: "Invalid YAML syntax (expected key: value or - item)",
   227→          line: lineNumber,
   228→          column: indent.length + 1,
   229→          context: line,
   230→        },
   231→      };
   232→    }
   233→  }
   234→
   235→  return { success: true, data: root };
   236→}
   237→
   238→/**
   239→ * Get the leading whitespace of a line.
   240→ */
   241→function getIndentation(line: string): string {
   242→  const match = line.match(/^(\s*)/);
   243→  return match ? match[1] : "";
   244→}
   245→
   246→/**
   247→ * Parse a value string and infer its type.
   248→ */
   249→function parseValue(value: string): any {
   250→  const trimmed = value.trim();
   251→
   252→  if (!trimmed || trimmed === "") {
   253→    return null;
   254→  }
   255→
   256→  // Handle quoted strings (preserve as-is)
   257→  if (
   258→    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
   259→    (trimmed.startsWith("'") && trimmed.endsWith("'"))
   260→  ) {
   261→    return trimmed.slice(1, -1);
   262→  }
   263→
   264→  // Handle null
   265→  if (trimmed === "null" || trimmed === "~") {
   266→    return null;
   267→  }
   268→
   269→  // Handle booleans
   270→  if (trimmed === "true") {
   271→    return true;
   272→  }
   273→  if (trimmed === "false") {
   274→    return false;
   275→  }
   276→
   277→  // Handle numbers
   278→  if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
   279→    return Number(trimmed);
   280→  }
   281→
   282→  // Default to string
   283→  return trimmed;
   284→}
