     1→/**
     2→ * Minimal YAML parser for common configuration syntax.
     3→ *
     4→ * This is a hand-written, zero-dependency YAML parser designed to handle
     5→ * typical configuration files. It supports:
     6→ * - Key-value pairs (key: value)
     7→ * - Nested objects (indentation-based)
     8→ * - Lists (- item syntax)
     9→ * - Comments (# lines)
    10→ * - Basic type inference (strings, numbers, booleans, null)
    11→ * - Quoted strings and escape sequences
    12→ *
    13→ * NOT supported (intentional):
    14→ * - YAML anchors (&ref, *ref)
    15→ * - YAML tags (!!type)
    16→ * - Flow syntax ({} and [])
    17→ * - Advanced YAML features (multiline strings, etc.)
    18→ * - Full YAML spec compliance
    19→ *
    20→ * Depth limit: 20 levels of nesting (prevents stack overflow)
    21→ *
    22→ * @module yaml-parser
    23→ */
    24→
    25→/**
    26→ * Result of parsing a YAML string.
    27→ */
    28→export interface ParseResult {
    29→  success: boolean;
    30→  data?: Record<string, any>;
    31→  error?: ParseError;
    32→}
    33→
    34→/**
    35→ * Error details from parsing failure.
    36→ */
    37→export interface ParseError {
    38→  message: string;
    39→  line: number;
    40→  column: number;
    41→  context: string; // the problematic line of text
    42→}
    43→
    44→interface StackFrame {
    45→  level: number;
    46→  key: string | null;
    47→  object: Record<string, any>;
    48→  listKey: string | null; // if this frame is for a list's parent key
    49→  listItemObject: Record<string, any> | null; // if this frame is for a list item object
    50→}
    51→
    52→/**
    53→ * Parse a YAML string into a JavaScript object.
    54→ * @param content - The YAML content to parse
    55→ * @returns ParseResult with success flag and either data or error
    56→ */
    57→export function parseYaml(content: string): ParseResult {
    58→  try {
    59→    const lines = content.split("\n");
    60→    return parseLines(lines);
    61→  } catch (err) {
    62→    return {
    63→      success: false,
    64→      error: {
    65→        message:
    66→          err instanceof Error ? err.message : "Unknown parsing error",
    67→        line: 0,
    68→        column: 0,
    69→        context: "",
    70→      },
    71→    };
    72→  }
    73→}
    74→
    75→/**
    76→ * Parse lines into a YAML structure.
    77→ */
    78→function parseLines(lines: string[]): ParseResult {
    79→  const root: Record<string, any> = {};
    80→  const stack: StackFrame[] = [
    81→    { level: -1, key: null, object: root, listKey: null, listItemObject: null },
    82→  ];
    83→
    84→  for (let i = 0; i < lines.length; i++) {
    85→    const line = lines[i];
    86→    const lineNumber = i + 1;
    87→
    88→    // Skip blank lines
    89→    if (line.trim() === "") {
    90→      continue;
    91→    }
    92→
    93→    // Skip comments
    94→    if (line.trim().startsWith("#")) {
    95→      continue;
    96→    }
    97→
    98→    const indent = getIndentation(line);
    99→    const indentLevel = indent.length / 2;
   100→    const content = line.slice(indent.length);
   101→
   102→    // Validate indentation
   103→    if (indent.length > 0 && indent.length % 2 !== 0) {
   104→      return {
   105→        success: false,
   106→        error: {
   107→          message: `Invalid indentation (expected multiple of 2 spaces, got ${indent.length})`,
   108→          line: lineNumber,
   109→          column: indent.length + 1,
   110→          context: line,
   111→        },
   112→      };
   113→    }
   114→
   115→    // Check depth limit
   116→    if (indentLevel > 20) {
   117→      return {
   118→        success: false,
   119→        error: {
   120→          message: "Maximum nesting depth exceeded (max 20 levels)",
   121→          line: lineNumber,
   122→          column: indent.length + 1,
   123→          context: line,
   124→        },
   125→      };
   126→    }
   127→
   128→    // Pop stack to current indent level
   129→    while (
   130→      stack.length > 1 &&
   131→      stack[stack.length - 1].level >= indentLevel
   132→    ) {
   133→      stack.pop();
   134→    }
   135→
   136→    const current = stack[stack.length - 1];
   137→
   138→    // Handle list items
   139→    if (content.startsWith("- ")) {
   140→      const value = content.slice(2).trim();
   141→
   142→      if (current.listKey) {
   143→        // We're adding to an existing array
   144→        if (!Array.isArray(current.object[current.listKey])) {
   145→          current.object[current.listKey] = [];
   146→        }
   147→
   148→        // Check if this list item is an object (either starts with key: value or has nested properties)
   149→        const startsWithKeyValue = value.includes(":");
   150→
   151→        // Also check if next lines are nested properties
   152→        let hasNestedProperties = false;
   153→        for (let j = i + 1; j < lines.length; j++) {
   154→          const nextLine = lines[j];
   155→          if (nextLine.trim() === "" || nextLine.trim().startsWith("#")) {
   156→            continue;
   157→          }
   158→          const nextIndent = getIndentation(nextLine);
   159→          const nextIndentLevel = nextIndent.length / 2;
   160→          if (nextIndentLevel > indentLevel) {
   161→            const nextContent = nextLine.slice(nextIndent.length);
   162→            // Check if the next line is a key-value pair (object property)
   163→            if (nextContent.includes(":") && !nextContent.startsWith("- ")) {
   164→              hasNestedProperties = true;
   165→            }
   166→          }
   167→          break;
   168→        }
   169→
   170→        if (startsWithKeyValue || hasNestedProperties) {
   171→          // This list item is an object
   172→          const listItemObj: Record<string, any> = {};
   173→          (current.object[current.listKey] as any[]).push(listItemObj);
   174→
   175→          // If the list item starts with a key-value pair, parse it now
   176→          if (startsWithKeyValue) {
   177→            const colonIdx = value.indexOf(":");
   178→            const key = value.slice(0, colonIdx).trim();
   179→            const keyValue = value.slice(colonIdx + 1).trim();
   180→
   181→            // Validate key
   182→            if (!/^[a-zA-Z_][a-zA-Z0-9_-]*$/.test(key)) {
   183→              return {
   184→                success: false,
   185→                error: {
   186→                  message: `Invalid key name: "${key}"`,
   187→                  line: lineNumber,
   188→                  column: indent.length + 1,
   189→                  context: line,
   190→                },
   191→              };
   192→            }
   193→
   194→            const typedValue = parseValue(keyValue);
   195→            listItemObj[key] = typedValue;
   196→          }
   197→
   198→          // Push a new frame for this list item object
   199→          stack.push({
   200→            level: indentLevel,
   201→            key: null,
   202→            object: listItemObj,
   203→            listKey: null,
   204→            listItemObject: listItemObj,
   205→          });
   206→        } else {
   207→          // Simple value in the list
   208→          const typedValue = parseValue(value);
   209→          (current.object[current.listKey] as any[]).push(typedValue);
   210→        }
   211→      }
   212→    } else if (content.includes(":")) {
   213→      // Key-value pair
   214→      const colonIdx = content.indexOf(":");
   215→      const key = content.slice(0, colonIdx).trim();
   216→      const value = content.slice(colonIdx + 1).trim();
   217→
   218→      // Validate key
   219→      if (!/^[a-zA-Z_][a-zA-Z0-9_-]*$/.test(key)) {
   220→        return {
   221→          success: false,
   222→          error: {
   223→            message: `Invalid key name: "${key}"`,
   224→            line: lineNumber,
   225→            column: indent.length + 1,
   226→            context: line,
   227→          },
   228→        };
   229→      }
   230→
   231→      // Determine which object to add this key to
   232→      // If we're inside a list item object, add to that; otherwise add to current.object
   233→      const targetObj = current.listItemObject || current.object;
   234→
   235→      if (value === "") {
   236→        // This key will have nested content
   237→        // Look ahead to see if the next line is a list item
   238→        let isListKey = false;
   239→        for (let j = i + 1; j < lines.length; j++) {
   240→          const nextLine = lines[j];
   241→          if (nextLine.trim() === "" || nextLine.trim().startsWith("#")) {
   242→            continue;
   243→          }
   244→          const nextIndent = getIndentation(nextLine);
   245→          const nextIndentLevel = nextIndent.length / 2;
   246→          if (nextIndentLevel > indentLevel) {
   247→            const nextContent = nextLine.slice(nextIndent.length);
   248→            if (nextContent.startsWith("- ")) {
   249→              isListKey = true;
   250→            }
   251→          }
   252→          break;
   253→        }
   254→
   255→        if (isListKey) {
   256→          // Initialize as an empty array that we'll populate
   257→          targetObj[key] = [];
   258→          // Push frame to track that this is a list key
   259→          stack.push({
   260→            level: indentLevel,
   261→            key,
   262→            object: targetObj,
   263→            listKey: key,
   264→            listItemObject: null,
   265→          });
   266→        } else {
   267→          // Regular nested object
   268→          const nested: Record<string, any> = {};
   269→          targetObj[key] = nested;
   270→          stack.push({
   271→            level: indentLevel,
   272→            key,
   273→            object: nested,
   274→            listKey: null,
   275→            listItemObject: null,
   276→          });
   277→        }
   278→      } else {
   279→        // Immediate value
   280→        const typedValue = parseValue(value);
   281→        targetObj[key] = typedValue;
   282→
   283→        // Update list key if we just assigned a value to what was a list key
   284→        if (current.listKey === key) {
   285→          current.listKey = null;
   286→        }
   287→      }
   288→    } else {
   289→      // Invalid syntax
   290→      return {
   291→        success: false,
   292→        error: {
   293→          message: "Invalid YAML syntax (expected key: value or - item)",
   294→          line: lineNumber,
   295→          column: indent.length + 1,
   296→          context: line,
   297→        },
   298→      };
   299→    }
   300→  }
   301→
   302→  return { success: true, data: root };
   303→}
   304→
   305→/**
   306→ * Get the leading whitespace of a line.
   307→ */
   308→function getIndentation(line: string): string {
   309→  const match = line.match(/^(\s*)/);
   310→  return match ? match[1] : "";
   311→}
   312→
   313→/**
   314→ * Parse a value string and infer its type.
   315→ */
   316→function parseValue(value: string): any {
   317→  const trimmed = value.trim();
   318→
   319→  if (!trimmed || trimmed === "") {
   320→    return null;
   321→  }
   322→
   323→  // Handle quoted strings (preserve as-is)
   324→  if (
   325→    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
   326→    (trimmed.startsWith("'") && trimmed.endsWith("'"))
   327→  ) {
   328→    return trimmed.slice(1, -1);
   329→  }
   330→
   331→  // Handle null
   332→  if (trimmed === "null" || trimmed === "~") {
   333→    return null;
   334→  }
   335→
   336→  // Handle booleans
   337→  if (trimmed === "true") {
   338→    return true;
   339→  }
   340→  if (trimmed === "false") {
   341→    return false;
   342→  }
   343→
   344→  // Handle numbers
   345→  if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
   346→    return Number(trimmed);
   347→  }
   348→
   349→  // Default to string
   350→  return trimmed;
   351→}
