import { describe, expect, test } from "bun:test";
import { writeFileSync, unlinkSync } from "fs";
import { join } from "path";

/**
 * Integration tests for the CLI validate-yaml command.
 * Tests the full command flow including file I/O, parsing, exit codes, and output.
 */

describe("CLI validate-yaml integration", () => {
  const testDir = "/tmp/yaml-test";
  const validYamlPath = join(testDir, "valid.yaml");
  const invalidYamlPath = join(testDir, "invalid.yaml");

  // Helper to write test files
  const writeTestFile = (path: string, content: string) => {
    // Ensure directory exists
    try {
      Bun.file(testDir).type();
    } catch {
      // Directory doesn't exist, we'll rely on writeFileSync with directory creation
    }
    writeFileSync(path, content);
  };

  const cleanupTestFile = (path: string) => {
    try {
      unlinkSync(path);
    } catch {
      // File may not exist, ignore
    }
  };

  test("CLI returns exit code 0 for valid YAML file", async () => {
    const validYaml = `name: test-app
version: 1.0
enabled: true
items:
  - id: 1
  - id: 2`;

    writeTestFile(validYamlPath, validYaml);

    try {
      const process = Bun.spawnSync(["bun", "run", "src/index.ts", "validate-yaml", validYamlPath], {
        cwd: "/tmp/rp1-evals/29793fdd/workspace",
      });

      expect(process.exitCode).toBe(0);
      const output = process.stdout.toString("utf-8");
      expect(output).toContain("YAML is valid");
    } finally {
      cleanupTestFile(validYamlPath);
    }
  });

  test("CLI returns exit code 1 for invalid YAML file (parse error)", async () => {
    const invalidYaml = `name: test-app
   version: 1.0`; // Invalid indentation (3 spaces)

