    63→      success: false,
    64→      error: {
    65→        message:
    66→          err instanceof Error ? err.message : "Unknown parsing error",
    67→        line: 0,
    68→        column: 0,
    69→        context: "",
    70→      },
    71→    };
    72→  }
    73→}
