    45→export async function validateYaml(filePath: string): Promise<ParseResult> {
    46→  try {
    47→    const file = Bun.file(filePath);
    48→    const exists = await file.exists();
    49→
    50→    if (!exists) {
    51→      return {
    52→        success: false,
    53→        error: {
    54→          message: `File not found: ${filePath}`,
    55→          line: 0,
    56→          column: 0,
    57→          context: "",
    58→        },
    59→      };
    60→    }
    61→
    62→    const content = await file.text();
    63→    const result = parseYaml(content);
    64→    return result;
    65→  } catch (err) {
    66→    const message =
    67→      err instanceof Error ? err.message : "Unknown error reading file";
    68→    return {
    69→      success: false,
    70→      error: {
    71→        message: `File error: ${message}`,
    72→        line: 0,
    73→        column: 0,
    74→        context: "",
    75→      },
    76→    };
    77→  }
    78→}
