/**
 * Minimal YAML parser for common configuration syntax.
 *
 * This is a hand-written, zero-dependency YAML parser designed to handle
 * typical configuration files. It supports:
 * - Key-value pairs (key: value)
 * - Nested objects (indentation-based)
 * - Lists (- item syntax)
 * - Comments (# lines)
 * - Basic type inference (strings, numbers, booleans, null)
 * - Quoted strings and escape sequences
 *
 * NOT supported (intentional):
 * - YAML anchors (&ref, *ref)
 * - YAML tags (!!type)
 * - Flow syntax ({} and [])
 * - Advanced YAML features (multiline strings, etc.)
 * - Full YAML spec compliance
 *
 * Depth limit: 20 levels of nesting (prevents stack overflow)
 *
 * @module yaml-parser
 */

/**
 * Result of parsing a YAML string.
 */
export interface ParseResult {
  success: boolean;
  data?: Record<string, any>;
  error?: ParseError;
}

/**
 * Error details from parsing failure.
 */
export interface ParseError {
  message: string;
  line: number;
  column: number;
  context: string; // the problematic line of text
}

/**
 * Parse a YAML string into a JavaScript object.
 * @param content - The YAML content to parse
 * @returns ParseResult with success flag and either data or error
 */
export function parseYaml(content: string): ParseResult {
  try {
    const lines = content.split("\n");
    const result = parseLines(lines);
    return result;
  } catch (err) {
    return {
      success: false,
      error: {
        message:
          err instanceof Error ? err.message : "Unknown parsing error",
        line: 0,
        column: 0,
        context: "",
      },
    };
  }
}

/**
 * Parse lines into a YAML structure.
 */
function parseLines(lines: string[]): ParseResult {
  // Validate indentation consistency
  const indentError = validateIndentation(lines);
  if (indentError) {
    return { success: false, error: indentError };
  }

  const root: Record<string, any> = {};
  const stack: Array<{
    level: number;
    object: Record<string, any> | any[];
    isArray: boolean;
  }> = [{ level: -1, object: root, isArray: false }];

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    const lineNumber = i + 1;
    i++;

    // Skip blank lines
    if (line.trim() === "") {
      continue;
    }

    // Skip comments
    if (line.trim().startsWith("#")) {
      continue;
    }

    const indent = getIndentation(line);
    const indentLevel = indent.length / 2;
    const content = line.slice(indent.length);

    // Check depth limit
    if (indentLevel > 20) {
      return {
        success: false,
        error: {
          message: "Maximum nesting depth exceeded (max 20 levels)",
          line: lineNumber,
          column: indent.length + 1,
          context: line,
        },
      };
    }

    // Pop stack to current level
    while (
      stack.length > 1 &&
      stack[stack.length - 1].level >= indentLevel
    ) {
      stack.pop();
    }

    const current = stack[stack.length - 1];

    // Handle list items
    if (content.startsWith("- ")) {
      const value = content.slice(2).trim();
      const parsedValue = parseValue(value);

      if (current.isArray) {
        (current.object as any[]).push(parsedValue);
      } else {
        // Convert current object to array-like structure
        // Find the last key and convert it to an array
        const keys = Object.keys(current.object);
        if (keys.length > 0) {
          const lastKey = keys[keys.length - 1];
          if (!Array.isArray(current.object[lastKey])) {
            current.object[lastKey] = [];
          }
          (current.object[lastKey] as any[]).push(parsedValue);
        }
      }
    } else if (content.includes(":")) {
      // Key-value pair
      const colonIdx = content.indexOf(":");
      const key = content.slice(0, colonIdx).trim();
      const valueStr = content.slice(colonIdx + 1).trim();

      // Validate key
      if (!/^[a-zA-Z_][a-zA-Z0-9_-]*$/.test(key)) {
        return {
          success: false,
          error: {
            message: `Invalid key name: "${key}"`,
            line: lineNumber,
            column: indent.length + 1,
            context: line,
          },
        };
      }

      if (valueStr === "") {
        // This is a nested object key
        const nested: Record<string, any> = {};
        if (current.isArray) {
          (current.object as any[]).push(nested);
        } else {
          (current.object as Record<string, any>)[key] = nested;
        }
        stack.push({
          level: indentLevel,
          object: nested,
          isArray: false,
        });
      } else {
        // Regular key-value
        const parsedValue = parseValue(valueStr);
        if (current.isArray) {
          (current.object as any[]).push({ [key]: parsedValue });
        } else {
          (current.object as Record<string, any>)[key] = parsedValue;
        }
      }
    } else {
      // Invalid syntax
      return {
        success: false,
        error: {
          message: "Invalid YAML syntax (expected key: value or - item)",
          line: lineNumber,
          column: indent.length + 1,
          context: line,
        },
      };
    }
  }

  return { success: true, data: root };
}

/**
 * Validate that indentation is consistent (multiples of 2 spaces).
 */
function validateIndentation(lines: string[]): ParseError | null {
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (line.trim() === "") {
      continue;
    }

    const indent = getIndentation(line);
    if (indent.length > 0 && indent.length % 2 !== 0) {
      return {
        message: `Invalid indentation (expected multiple of 2 spaces, got ${indent.length})`,
        line: i + 1,
        column: indent.length + 1,
        context: line,
      };
    }
  }

  return null;
}

/**
 * Get the leading whitespace of a line.
 */
function getIndentation(line: string): string {
  const match = line.match(/^(\s*)/);
  return match ? match[1] : "";
}

/**
 * Parse a value string and infer its type.
 */
function parseValue(value: string): any {
  const trimmed = value.trim();

  if (!trimmed || trimmed === "") {
    return null;
  }

  // Handle quoted strings (preserve as-is)
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }

  // Handle null
  if (trimmed === "null" || trimmed === "~") {
    return null;
  }

  // Handle booleans
  if (trimmed === "true") {
    return true;
  }
  if (trimmed === "false") {
    return false;
  }

  // Handle numbers
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
    return Number(trimmed);
  }

  // Default to string
  return trimmed;
}

