input.content:
/**
 * Minimal YAML parser for common configuration syntax.
 *
 * This is a hand-written, zero-dependency YAML parser designed to handle
 * typical configuration files. It supports:
 * - Key-value pairs (key: value)
 * - Nested objects (indentation-based)
 * - Lists (- item syntax)
 * - Comments (# lines)
 * - Basic type inference (strings, numbers, booleans, null)
 * - Quoted strings and escape sequences
 *
 * NOT supported (intentional):
 * - YAML anchors (&ref, *ref)
 * - YAML tags (!!type)
 * - Flow syntax ({} and [])
 * - Advanced YAML features (multiline strings, etc.)
 * - Full YAML spec compliance
 *
 * Depth limit: 20 levels of nesting (prevents stack overflow)
 *
 * @module yaml-parser
 */

/**
 * Result of parsing a YAML string.
 */
export interface ParseResult {
  success: boolean;
  data?: Record<string, any>;
  error?: ParseError;
}

/**
 * Error details from parsing failure.
 */
export interface ParseError {
  message: string;
  line: number;
  column: number;
  context: string; // the problematic line of text
}

/**
 * Parse a YAML string into a JavaScript object.
 * @param content - The YAML content to parse
 * @returns ParseResult with success flag and either data or error
 */
export function parseYaml(content: string): ParseResult {
  try {
    const lines = content.split("\n");
    const result = parseLines(lines);
    return result;
  } catch (err) {
    return {
      success: false,
      error: {
        message:
          err instanceof Error ? err.message : "Unknown parsing error",
        line: 0,
        column: 0,
        context: "",
      },
    };
  }
}

interface ParsedLine {
  type: "blank" | "comment" | "key-value" | "list-item";
  key?: string;
  value?: string;
  indentLevel: number;
  lineNumber: number;
  rawLine: string;
}

/**
 * Parse lines into a YAML structure.
 */
function parseLines(lines: string[]): ParseResult {
  // First pass: validate and parse all lines
  const parsedLines: ParsedLine[] = [];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNumber = i + 1;

    // Skip blank lines
    if (line.trim() === "") {
      parsedLines.push({
        type: "blank",
        indentLevel: 0,
        lineNumber,
        rawLine: line,
      });
      continue;
    }

    // Skip comments
    if (line.trim().startsWith("#")) {
      parsedLines.push({
        type: "comment",
        indentLevel: 0,
        lineNumber,
        rawLine: line,
      });
      continue;
    }

    const indent = getIndentation(line);
    const indentLevel = indent.length / 2;

    // Validate indentation
    if (indent.length > 0 && indent.length % 2 !== 0) {
      return {
        success: false,
        error: {
          message: `Invalid indentation (expected multiple of 2 spaces, got ${indent.length})`,
          line: lineNumber,
          column: indent.length + 1,
          context: line,
        },
      };
    }

    // Check depth limit
    if (indentLevel > 20) {
      return {
        success: false,
        error: {
          message: "Maximum nesting depth exceeded (max 20 levels)",
          line: lineNumber,
          column: indent.length + 1,
          context: line,
        },
      };
    }

    const content = line.slice(indent.length);

    // Parse list items
    if (content.startsWith("- ")) {
      parsedLines.push({
        type: "list-item",
        value: content.slice(2).trim(),
        indentLevel,
        lineNumber,
        rawLine: line,
      });
      continue;
    }

    // Parse key-value pairs
    if (content.includes(":")) {
      const colonIdx = content.indexOf(":");
      const key = content.slice(0, colonIdx).trim();
      const value = content.slice(colonIdx + 1).trim();

      // Validate key
      if (!/^[a-zA-Z_][a-zA-Z0-9_-]*$/.test(key)) {
        return {
          success: false,
          error: {
            message: `Invalid key name: "${key}"`,
            line: lineNumber,
            column: indent.length + 1,
            context: line,
          },
        };
      }

      parsedLines.push({
        type: "key-value",
        key,
        value,
        indentLevel,
        lineNumber,
        rawLine: line,
      });
      continue;
    }

    // Unrecognized syntax
    return {
      success: false,
      error: {
        message: "Invalid YAML syntax (expected key: value or - item)",
        line: lineNumber,
        column: indent.length + 1,
        context: line,
      },
    };
  }

  // Second pass: build the tree structure
  const root: Record<string, any> = {};
  const stack: Array<{
    level: number;
    key: string | null;
    object: any;
  }> = [{ level: -1, key: null, object: root }];

  for (const parsed of parsedLines) {
    if (parsed.type === "blank" || parsed.type === "comment") {
      continue;
    }

    // Pop stack to appropriate level
    while (
      stack.length > 1 &&
      stack[stack.length - 1].level >= parsed.indentLevel
    ) {
      stack.pop();
    }

    const current = stack[stack.length - 1];

    if (parsed.type === "key-value") {
      const key = parsed.key!;
      const value = parsed.value!;

      if (value === "") {
        // This key will have children - create a container
        const container: Record<string, any> = {};
        current.object[key] = container;
        stack.push({
          level: parsed.indentLevel,
          key,
          object: container,
        });
      } else {
        // Immediate value
        const typedValue = parseValue(value);
        current.object[key] = typedValue;
      }
    } else if (parsed.type === "list-item") {
      // List items belong to the parent key
      const value = parsed.value!;
      const typedValue = parseValue(value);

      // The current.object should contain the last key that was set
      // We need to convert it to an array if it's not already
      const parentKey = stack.length > 0 ? stack[stack.length - 1].key : null;

      if (parentKey) {
        const parentObj = stack[stack.length - 1].object;
        if (!Array.isArray(parentObj[parentKey])) {
          parentObj[parentKey] = [];
        }
        (parentObj[parentKey] as any[]).push(typedValue);
      }
    }
  }

  return { success: true, data: root };
}

/**
 * Get the leading whitespace of a line.
 */
function getIndentation(line: string): string {
  const match = line.match(/^(\s*)/);
  return match ? match[1] : "";
}

/**
 * Parse a value string and infer its type.
 */
function parseValue(value: string): any {
  const trimmed = value.trim();

  if (!trimmed || trimmed === "") {
    return null;
  }

  // Handle quoted strings (preserve as-is)
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }

  // Handle null
  if (trimmed === "null" || trimmed === "~") {
    return null;
  }

  // Handle booleans
  if (trimmed === "true") {
    return true;
  }
  if (trimmed === "false") {
    return false;
  }

  // Handle numbers
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
    return Number(trimmed);
  }

  // Default to string
  return trimmed;
}

