/**
 * Main entry point for the rp1 eval test project.
 */

import { greet, validateYaml } from "./utils";

const command = process.argv[2];
const arg = process.argv[3];

if (command === "validate-yaml") {
  if (!arg) {
    console.error("Error: File path required for validate-yaml command");
    console.error("Usage: bun run src/index.ts validate-yaml <file-path>");
    process.exit(1);
  }

  const result = await validateYaml(arg);
  if (result.success) {
    console.log("YAML is valid");
    process.exit(0);
  } else {
    const error = result.error;
    if (error?.message.includes("File not found")) {
      console.error(error.message);
      process.exit(2);
    } else {
      const line = error?.line || 0;
      const column = error?.column || 0;
      const message = error?.message || "Unknown error";
      const context = error?.context ? ` (${error.context})` : "";
      console.error(`Line ${line}, Column ${column}: ${message}${context}`);
      process.exit(1);
    }
  }
} else {
  const name = command ?? "World";
  console.log(greet(name));
}

/**
 * Utility functions for the eval test project.
 */

import { parseYaml, type ParseResult } from "./yaml-parser.ts";

/**
 * Greet someone by name.
 */
export function greet(name: string): string {
  return `Hello, ${name}!`;
}

/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * Validate a YAML file.
 *
 * Reads a YAML file from the provided path and validates its syntax using the
 * built-in YAML parser. Returns a ParseResult indicating success or failure.
 *
 * @param filePath - The relative or absolute path to the YAML file to validate
 * @returns A Promise that resolves to a ParseResult with either parsed data or error details
 *
 * @example
 * ```typescript
 * const result = await validateYaml('config.yaml');
 * if (result.success) {
 *   console.log('YAML is valid:', result.data);
 * } else {
 *   console.error('Parse error at line', result.error?.line, ':', result.error?.message);
 * }
 * ```
 *
 * Error handling:
 * - File not found: Returns ParseResult with success=false and error describing the file issue
 * - Parse error: Returns ParseResult with success=false and error from the parser
 * - Both error types are wrapped in the same ParseResult interface for consistency
 */
export async function validateYaml(filePath: string): Promise<ParseResult> {
  try {
    const file = Bun.file(filePath);
    const exists = await file.exists();

    if (!exists) {
      return {
        success: false,
        error: {
          message: `File not found: ${filePath}`,
          line: 0,
          column: 0,
          context: "",
        },
      };
    }

    const content = await file.text();
    const result = parseYaml(content);
    return result;
  } catch (err) {
    const message =
      err instanceof Error ? err.message : "Unknown error reading file";
    return {
      success: false,
      error: {
        message: `File error: ${message}`,
        line: 0,
        column: 0,
        context: "",
      },
    };
  }
}

/**
 * Minimal YAML parser for common configuration syntax.
 *
 * This is a hand-written, zero-dependency YAML parser designed to handle
 * typical configuration files. It supports:
 * - Key-value pairs (key: value)
 * - Nested objects (indentation-based)
 * - Lists (- item syntax)
 * - Comments (# lines)
 * - Basic type inference (strings, numbers, booleans, null)
 * - Quoted strings and escape sequences
 *
 * NOT supported (intentional):
 * - YAML anchors (&ref, *ref)
 * - YAML tags (!!type)
 * - Flow syntax ({} and [])
 * - Advanced YAML features (multiline strings, etc.)
 * - Full YAML spec compliance
 *
 * Depth limit: 20 levels of nesting (prevents stack overflow)
 *
 * @module yaml-parser
 */

/**
 * Result of parsing a YAML string.
 */
export interface ParseResult {
  success: boolean;
  data?: Record<string, any>;
  error?: ParseError;
}

/**
 * Error details from parsing failure.
 */
export interface ParseError {
  message: string;
  line: number;
  column: number;
  context: string; // the problematic line of text
}

interface StackFrame {
  level: number;
  key: string | null;
  object: Record<string, any>;
  listKey: string | null; // if this frame is for a list's parent key
  listItemObject: Record<string, any> | null; // if this frame is for a list item object
}

/**
 * Parse a YAML string into a JavaScript object.
 * @param content - The YAML content to parse
 * @returns ParseResult with success flag and either data or error
 */
export function parseYaml(content: string): ParseResult {
  try {
    const lines = content.split("\n");
    return parseLines(lines);
  } catch (err) {
    return {
      success: false,
      error: {
        message:
          err instanceof Error ? err.message : "Unknown parsing error",
        line: 0,
        column: 0,
        context: "",
      },
    };
  }
}

/**
 * Parse lines into a YAML structure.
 */
function parseLines(lines: string[]): ParseResult {
  const root: Record<string, any> = {};
  const stack: StackFrame[] = [
    { level: -1, key: null, object: root, listKey: null, listItemObject: null },
  ];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNumber = i + 1;

    // Skip blank lines
    if (line.trim() === "") {
      continue;
    }

    // Skip comments
    if (line.trim().startsWith("#")) {
      continue;
    }

    const indent = getIndentation(line);
    const indentLevel = indent.length / 2;
    const content = line.slice(indent.length);

    // Validate indentation
    if (indent.length > 0 && indent.length % 2 !== 0) {
      return {
        success: false,
        error: {
          message: `Invalid indentation (expected multiple of 2 spaces, got ${indent.length})`,
          line: lineNumber,
          column: indent.length + 1,
          context: line,
        },
      };
    }

    // Check depth limit
    if (indentLevel > 20) {
      return {
        success: false,
        error: {
          message: "Maximum nesting depth exceeded (max 20 levels)",
          line: lineNumber,
          column: indent.length + 1,
          context: line,
        },
      };
    }

    // Pop stack to current indent level
    while (
      stack.length > 1 &&
      stack[stack.length - 1].level >= indentLevel
    ) {
      stack.pop();
    }

    const current = stack[stack.length - 1];

    // Handle list items
    if (content.startsWith("- ")) {
      const value = content.slice(2).trim();

      if (current.listKey) {
        // We're adding to an existing array
        if (!Array.isArray(current.object[current.listKey])) {
          current.object[current.listKey] = [];
        }

        // Check if this list item is an object (either starts with key: value or has nested properties)
        const startsWithKeyValue = value.includes(":");

        // Also check if next lines are nested properties
        let hasNestedProperties = false;
        for (let j = i + 1; j < lines.length; j++) {
          const nextLine = lines[j];
          if (nextLine.trim() === "" || nextLine.trim().startsWith("#")) {
            continue;
          }
          const nextIndent = getIndentation(nextLine);
          const nextIndentLevel = nextIndent.length / 2;
          if (nextIndentLevel > indentLevel) {
            const nextContent = nextLine.slice(nextIndent.length);
            // Check if the next line is a key-value pair (object property)
            if (nextContent.includes(":") && !nextContent.startsWith("- ")) {
              hasNestedProperties = true;
            }
          }
          break;
        }

        if (startsWithKeyValue || hasNestedProperties) {
          // This list item is an object
          const listItemObj: Record<string, any> = {};
          (current.object[current.listKey] as any[]).push(listItemObj);

          // If the list item starts with a key-value pair, parse it now
          if (startsWithKeyValue) {
            const colonIdx = value.indexOf(":");
            const key = value.slice(0, colonIdx).trim();
            const keyValue = value.slice(colonIdx + 1).trim();

            // Validate key
            if (!/^[a-zA-Z_][a-zA-Z0-9_-]*$/.test(key)) {
              return {
                success: false,
                error: {
                  message: `Invalid key name: "${key}"`,
                  line: lineNumber,
                  column: indent.length + 1,
                  context: line,
                },
              };
            }

            const typedValue = parseValue(keyValue);
            listItemObj[key] = typedValue;
          }

          // Push a new frame for this list item object
          stack.push({
            level: indentLevel,
            key: null,
            object: listItemObj,
            listKey: null,
            listItemObject: listItemObj,
          });
        } else {
          // Simple value in the list
          const typedValue = parseValue(value);
          (current.object[current.listKey] as any[]).push(typedValue);
        }
      }
    } else if (content.includes(":")) {
      // Key-value pair
      const colonIdx = content.indexOf(":");
      const key = content.slice(0, colonIdx).trim();
      const value = content.slice(colonIdx + 1).trim();

      // Validate key
      if (!/^[a-zA-Z_][a-zA-Z0-9_-]*$/.test(key)) {
        return {
          success: false,
          error: {
            message: `Invalid key name: "${key}"`,
            line: lineNumber,
            column: indent.length + 1,
            context: line,
          },
        };
      }

      // Determine which object to add this key to
      // If we're inside a list item object, add to that; otherwise add to current.object
      const targetObj = current.listItemObject || current.object;

      if (value === "") {
        // This key will have nested content
        // Look ahead to see if the next line is a list item
        let isListKey = false;
        for (let j = i + 1; j < lines.length; j++) {
          const nextLine = lines[j];
          if (nextLine.trim() === "" || nextLine.trim().startsWith("#")) {
            continue;
          }
          const nextIndent = getIndentation(nextLine);
          const nextIndentLevel = nextIndent.length / 2;
          if (nextIndentLevel > indentLevel) {
            const nextContent = nextLine.slice(nextIndent.length);
            if (nextContent.startsWith("- ")) {
              isListKey = true;
            }
          }
          break;
        }

        if (isListKey) {
          // Initialize as an empty array that we'll populate
          targetObj[key] = [];
          // Push frame to track that this is a list key
          stack.push({
            level: indentLevel,
            key,
            object: targetObj,
            listKey: key,
            listItemObject: null,
          });
        } else {
          // Regular nested object
          const nested: Record<string, any> = {};
          targetObj[key] = nested;
          stack.push({
            level: indentLevel,
            key,
            object: nested,
            listKey: null,
            listItemObject: null,
          });
        }
      } else {
        // Immediate value
        const typedValue = parseValue(value);
        targetObj[key] = typedValue;

        // Update list key if we just assigned a value to what was a list key
        if (current.listKey === key) {
          current.listKey = null;
        }
      }
    } else {
      // Invalid syntax
      return {
        success: false,
        error: {
          message: "Invalid YAML syntax (expected key: value or - item)",
          line: lineNumber,
          column: indent.length + 1,
          context: line,
        },
      };
    }
  }

  return { success: true, data: root };
}

/**
 * Get the leading whitespace of a line.
 */
function getIndentation(line: string): string {
  const match = line.match(/^(\s*)/);
  return match ? match[1] : "";
}

/**
 * Parse a value string and infer its type.
 */
function parseValue(value: string): any {
  const trimmed = value.trim();

  if (!trimmed || trimmed === "") {
    return null;
  }

  // Handle quoted strings (preserve as-is)
  if (
    (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }

  // Handle null
  if (trimmed === "null" || trimmed === "~") {
    return null;
  }

  // Handle booleans
  if (trimmed === "true") {
    return true;
  }
  if (trimmed === "false") {
    return false;
  }

  // Handle numbers
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
    return Number(trimmed);
  }

  // Default to string
  return trimmed;
}

import { describe, expect, test } from "bun:test";
import { parseYaml } from "./yaml-parser";

describe("yaml-parser", () => {
  test("parses simple key-value pairs", () => {
    const yaml = `key1: value1
key2: value2`;
    const result = parseYaml(yaml);
    expect(result.success).toBe(true);
    expect(result.data).toEqual({ key1: "value1", key2: "value2" });
  });

  test("parses nested objects with indentation", () => {
    const yaml = `parent:
  child1: value1
  child2: value2`;
    const result = parseYaml(yaml);
    expect(result.success).toBe(true);
    expect(result.data).toEqual({
      parent: { child1: "value1", child2: "value2" },
    });
  });

  test("parses lists with simple values", () => {
    const yaml = `items:
  - item1
  - item2
  - item3`;
    const result = parseYaml(yaml);
    expect(result.success).toBe(true);
    expect(result.data).toEqual({ items: ["item1", "item2", "item3"] });
  });

  test("parses lists with objects (nested key-value pairs in list items)", () => {
    const yaml = `items:
  - name: first
    value: 1
  - name: second
    value: 2`;
    const result = parseYaml(yaml);
    expect(result.success).toBe(true);
    expect(result.data).toEqual({
      items: [
        { name: "first", value: 1 },
        { name: "second", value: 2 },
      ],
    });
  });

  test("parses comments correctly", () => {
    const yaml = `# This is a comment
key1: value1
# Another comment
key2: value2`;
    const result = parseYaml(yaml);
    expect(result.success).toBe(true);
    expect(result.data).toEqual({ key1: "value1", key2: "value2" });
  });

  test("parses quoted strings", () => {
    const yaml = `key1: "quoted value"
key2: 'single quoted'`;
    const result = parseYaml(yaml);
    expect(result.success).toBe(true);
    expect(result.data).toEqual({
      key1: "quoted value",
      key2: "single quoted",
    });
  });

  test("parses basic types (numbers, booleans, null)", () => {
    const yaml = `number: 42
float: 3.14
boolean_true: true
boolean_false: false
null_value: null`;
    const result = parseYaml(yaml);
    expect(result.success).toBe(true);
    expect(result.data).toEqual({
      number: 42,
      float: 3.14,
      boolean_true: true,
      boolean_false: false,
      null_value: null,
    });
  });

  test("detects indentation errors", () => {
    const yaml = `key1: value1
   key2: value2`; // 3 spaces instead of 2 or 0
    const result = parseYaml(yaml);
    expect(result.success).toBe(false);
    expect(result.error).toBeDefined();
    expect(result.error?.message).toContain("Invalid indentation");
  });

  test("detects invalid key names", () => {
    const yaml = `123-invalid: value`; // Keys must start with letter or underscore
    const result = parseYaml(yaml);
