import { describe, expect, test } from "bun:test";
import { writeFileSync, unlinkSync } from "fs";
import { join } from "path";

/**
 * Integration tests for the CLI validate-yaml command.
 * Tests the full command flow including file I/O, parsing, exit codes, and output.
 */

describe("CLI validate-yaml integration", () => {
  const testDir = "/tmp/yaml-test";
  const validYamlPath = join(testDir, "valid.yaml");
  const invalidYamlPath = join(testDir, "invalid.yaml");

  // Helper to write test files
  const writeTestFile = (path: string, content: string) => {
    // Ensure directory exists
    try {
      Bun.file(testDir).type();
    } catch {
      // Directory doesn't exist, we'll rely on writeFileSync with directory creation
    }
    writeFileSync(path, content);
  };

  const cleanupTestFile = (path: string) => {
    try {
      unlinkSync(path);
    } catch {
      // File may not exist, ignore
    }
  };

  test("CLI returns exit code 0 for valid YAML file", async () => {
    const validYaml = `name: test-app
version: 1.0
enabled: true
items:
  - id: 1
  - id: 2`;

    writeTestFile(validYamlPath, validYaml);

    try {
      const process = Bun.spawnSync(["bun", "run", "src/index.ts", "validate-yaml", validYamlPath], {
        cwd: "/tmp/rp1-evals/29793fdd/workspace",
      });

      expect(process.exitCode).toBe(0);
      const output = process.stdout.toString("utf-8");
      expect(output).toContain("YAML is valid");
    } finally {
      cleanupTestFile(validYamlPath);
    }
  });

  test("CLI returns exit code 1 for invalid YAML file (parse error)", async () => {
    const invalidYaml = `name: test-app
   version: 1.0`; // Invalid indentation (3 spaces)

    writeTestFile(invalidYamlPath, invalidYaml);

    try {
      const process = Bun.spawnSync(["bun", "run", "src/index.ts", "validate-yaml", invalidYamlPath], {
        cwd: "/tmp/rp1-evals/29793fdd/workspace",
      });

      expect(process.exitCode).toBe(1);
      const output = process.stderr.toString("utf-8");
      expect(output).toContain("Line");
      expect(output).toContain("Column");
    } finally {
      cleanupTestFile(invalidYamlPath);
    }
  });

  test("CLI returns exit code 2 for file-not-found error", async () => {
    const nonexistentPath = join(testDir, "nonexistent.yaml");

    const process = Bun.spawnSync(["bun", "run", "src/index.ts", "validate-yaml", nonexistentPath], {
      cwd: "/tmp/rp1-evals/29793fdd/workspace",
    });

    expect(process.exitCode).toBe(2);
    const output = process.stderr.toString("utf-8");
    expect(output).toContain("File not found");
  });

  test("CLI prints error message on validation failure", async () => {
    const invalidYaml = `parent:
    child: value`; // Invalid indentation (4 spaces instead of 2)

    writeTestFile(invalidYamlPath, invalidYaml);

    try {
      const process = Bun.spawnSync(["bun", "run", "src/index.ts", "validate-yaml", invalidYamlPath], {
        cwd: "/tmp/rp1-evals/29793fdd/workspace",
      });

      expect(process.exitCode).toBe(1);
      const output = process.stderr.toString("utf-8");
      expect(output.length).toBeGreaterThan(0);
      expect(output).toMatch(/Line \d+, Column \d+:/);
    } finally {
      cleanupTestFile(invalidYamlPath);
    }
  });

  test("CLI prints minimal output on success", async () => {
    const validYaml = `key: value`;

    writeTestFile(validYamlPath, validYaml);

    try {
      const process = Bun.spawnSync(["bun", "run", "src/index.ts", "validate-yaml", validYamlPath], {
        cwd: "/tmp/rp1-evals/29793fdd/workspace",
      });

      expect(process.exitCode).toBe(0);
      const output = process.stdout.toString("utf-8");
      // Verify minimal output - just the success message
      expect(output.trim()).toBe("YAML is valid");
    } finally {
      cleanupTestFile(validYamlPath);
    }
  });

  test("CLI validates complex YAML structure", async () => {
    const complexYaml = `application:
  name: my-service
  version: 2.0
  debug: false
  database:
    host: localhost
    port: 5432
    credentials:
      user: admin
      password: secret
  servers:
    - name: primary
      address: 192.168.1.1
      port: 8080
    - name: backup
      address: 192.168.1.2
      port: 8081`;

    writeTestFile(validYamlPath, complexYaml);

    try {
      const process = Bun.spawnSync(["bun", "run", "src/index.ts", "validate-yaml", validYamlPath], {
        cwd: "/tmp/rp1-evals/29793fdd/workspace",
      });

      expect(process.exitCode).toBe(0);
      const output = process.stdout.toString("utf-8");
      expect(output).toContain("YAML is valid");
    } finally {
      cleanupTestFile(validYamlPath);
    }
  });

  test("CLI reports error for deeply nested invalid YAML", async () => {
    const invalidYaml = `level1:
  level2:
    level3:
      level4:
       level5: value`; // 7 spaces on last line (not a multiple of 2)

    writeTestFile(invalidYamlPath, invalidYaml);

    try {
      const process = Bun.spawnSync(["bun", "run", "src/index.ts", "validate-yaml", invalidYamlPath], {
        cwd: "/tmp/rp1-evals/29793fdd/workspace",
      });

      expect(process.exitCode).toBe(1);
      const output = process.stderr.toString("utf-8");
      expect(output).toContain("Invalid indentation");
    } finally {
      cleanupTestFile(invalidYamlPath);
    }
  });
});

