    21→/**
    22→ * Validate a YAML file.
    23→ *
    24→ * Reads a YAML file from the provided path and validates its syntax using the
    25→ * built-in YAML parser. Returns a ParseResult indicating success or failure.
    26→ *
    27→ * @param filePath - The relative or absolute path to the YAML file to validate
    28→ * @returns A Promise that resolves to a ParseResult with either parsed data or error details
    29→ *
    30→ * @example
    31→ * ```typescript
    32→ * const result = await validateYaml('config.yaml');
    33→ * if (result.success) {
    34→ *   console.log('YAML is valid:', result.data);
    35→ * } else {
    36→ *   console.error('Parse error at line', result.error?.line, ':', result.error?.message);
    37→ * }
    38→ * ```
    39→ *
    40→ * Error handling:
    41→ * - File not found: Returns ParseResult with success=false and error describing the file issue
    42→ * - Parse error: Returns ParseResult with success=false and error from the parser
    43→ * - Both error types are wrapped in the same ParseResult interface for consistency
    44→ */
    45→export async function validateYaml(filePath: string): Promise<ParseResult> {
    46→  try {
    47→    const file = Bun.file(filePath);
    48→    const exists = await file.exists();
    49→
    50→    if (!exists) {
    51→      return {
    52→        success: false,
    53→        error: {
    54→          message: `File not found: ${filePath}`,
    55→          line: 0,
    56→          column: 0,
    57→          context: "",
    58→        },
    59→      };
